/**
 * "Next check": when a word comes back, in words (SRS v2). It replaces
 * "Due in N days" wherever the feature is on, and always names the date,
 * because "in 12 days" alone makes the reader count.
 */
import type { Progress } from '@lexpad/core';
import { t } from '@/i18n/index.js';

const DAY_MS = 86_400_000;

/** A day index as a short date in the reader's locale: "Mon 20 Oct". */
export function shortDate(day: number): string {
  // A day index is a wall-clock date, so it is formatted in UTC, where the
  // index was made, never in the device's zone (which could shift it a day).
  return new Intl.DateTimeFormat(undefined, {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    timeZone: 'UTC',
  }).format(new Date(day * DAY_MS));
}

/** When a word is checked next, as a sentence, and whether that is today. */
export interface NextCheck {
  text: string;
  /** Due today or overdue. */
  today: boolean;
  /** Never practised, so there is no date yet. */
  unseen: boolean;
}

/** The word page's line: "Next check: in 12 days (Mon 20 Oct)". */
export function nextCheck(progress: Pick<Progress, 'dueDay'> | undefined, today: number): NextCheck {
  if (progress === undefined) return { text: t('schedule.notPractised'), today: false, unseen: true };
  const days = progress.dueDay - today;
  if (days <= 0) return { text: t('schedule.nextToday'), today: true, unseen: false };
  if (days === 1) return { text: t('schedule.nextTomorrow'), today: false, unseen: false };
  return {
    text: t('schedule.nextIn', { count: days, date: shortDate(progress.dueDay) }),
    today: false,
    unseen: false,
  };
}

/** The notebook row's shorter line: "Next check in 12 days". */
export function nextCheckShort(progress: Pick<Progress, 'dueDay'> | undefined, today: number): NextCheck {
  if (progress === undefined) return { text: t('schedule.notPractised'), today: false, unseen: true };
  const days = progress.dueDay - today;
  if (days <= 0) return { text: t('schedule.listToday'), today: true, unseen: false };
  if (days === 1) return { text: t('schedule.listTomorrow'), today: false, unseen: false };
  return { text: t('schedule.listIn', { count: days }), today: false, unseen: false };
}
